// One item with this week's broken links, most important first (internal, on many pages).
const cfg = $('Configure').first().json;
const keep = cfg.includeWarnings ? ['error', 'warning'] : ['error'];
const broken = $input.all().map(i => i.json).filter(r => r.url && keep.includes(r.severity)).map(r => ({
  url: r.url,
  status: r.status ?? '',
  problem: r.problem || '',
  type: `${r.linkType || ''} ${r.kind || 'link'}`.trim(),
  pages: r.foundOnCount || (r.foundOn || []).length || 1,
  found_on: (r.foundOn || []).slice(0, 3).map(s => s.page).join(' | '),
  link_text: ((r.foundOn || [])[0] || {}).text || '',
}));
broken.sort((a, b) => (a.type.startsWith('internal') ? 0 : 1) - (b.type.startsWith('internal') ? 0 : 1) || b.pages - a.pages);
return [{ json: { site: cfg.siteUrl, broken } }];

// Compare with the latest earlier week in the log: new, still broken, fixed.
const { site, broken } = $('Keep broken links').first().json;
const today = new Date().toISOString().slice(0, 10);
const log = $input.all().map(i => i.json).filter(r => r.url && r.site === site && r.week && r.week < today && r.state !== 'fixed');
const lastWeek = log.reduce((m, r) => (r.week > m ? r.week : m), '');
const before = new Set(log.filter(r => r.week === lastWeek).map(r => r.url));
const now = new Set(broken.map(r => r.url));
const rows = broken.map(r => ({ week: today, site, state: before.has(r.url) ? 'still broken' : 'new', ...r }));
const fixed = [...before].filter(u => !now.has(u)).map(url => ({ week: today, site, state: 'fixed', url }));
return [{ json: { site, today, lastWeek, rows, fixed,
  counts: { new: rows.filter(r => r.state === 'new').length, still: rows.filter(r => r.state !== 'new').length, fixed: fixed.length } } }];

// One sheet row per broken or fixed link.
const { rows, fixed } = $input.first().json;
return [...rows, ...fixed].map(json => ({ json }));

const esc = s => String(s ?? '').replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
// HTML report: new first, then still broken, then fixed.
const cfg = $('Configure').first().json;
const { site, rows, fixed, counts, lastWeek } = $('Compare with last week').first().json;
const host = new URL(site).hostname;
const table = list => `<table cellpadding="5" style="border-collapse:collapse;font-size:13px"><tr><th align="left">Broken link</th><th align="left">Status</th><th align="left">Pages</th><th align="left">First page with it</th></tr>${list.slice(0, 60).map(r => `<tr><td><a href="${esc(r.url)}">${esc(r.url.slice(0, 80))}</a><br><small>${esc(r.type)}${r.link_text ? ` · "${esc(r.link_text)}"` : ''}</small></td><td>${esc(r.status || r.problem)}</td><td>${r.pages}</td><td>${esc((r.found_on || '').split(' | ')[0])}</td></tr>`).join('')}</table>${list.length > 60 ? `<p>…and ${list.length - 60} more in the sheet.</p>` : ''}`;
const parts = [];
if (counts.new) parts.push(`<h3>New this week (${counts.new})</h3>${table(rows.filter(r => r.state === 'new'))}`);
if (counts.still) parts.push(`<h3>Still broken since ${esc(lastWeek)} (${counts.still})</h3>${table(rows.filter(r => r.state !== 'new'))}`);
if (counts.fixed) parts.push(`<h3>Fixed (${counts.fixed})</h3><ul>${fixed.slice(0, 60).map(r => `<li>${esc(r.url)}</li>`).join('')}</ul>`);
return [{ json: {
  sendTo: cfg.sendTo,
  subject: `${host}: ${counts.new} new, ${counts.still} still broken, ${counts.fixed} fixed`,
  html: `<div style="font-family:Arial,sans-serif;font-size:14px"><p>Weekly link check for <a href="${esc(site)}">${esc(site)}</a>.</p>${parts.join('')}</div>`,
} }];
